enum ExtraType { NONE, WIDE, NO_BALL, BYE, LEG_BYE }
enum MatchState { NOT_STARTED, IN_PROGRESS, COMPLETED }

record Wicket(String dismissedPlayerId, String dismissalType) {}
record Player(String playerId, String name) {}
record Team(String teamId, String teamName, List<Player> players) {}

class Ball {
    final int runs;              // runs scored off bat
    final ExtraType extraType;
    final int extraRuns;         // extra runs (1 for wide + any additional)
    final Wicket wicket;         // null if no wicket
    final boolean isBoundary;
    final String strikerId;
    final String bowlerId;

    public Ball(int runs, ExtraType extra, int extraRuns,
                Wicket wicket, boolean boundary, String striker, String bowler) {
        this.runs = runs; this.extraType = extra; this.extraRuns = extraRuns;
        this.wicket = wicket; this.isBoundary = boundary;
        this.strikerId = striker; this.bowlerId = bowler;
    }

    public boolean isLegalDelivery() {
        return extraType != ExtraType.WIDE && extraType != ExtraType.NO_BALL;
    }
    public int totalRuns() { return runs + extraRuns; }
}

class BatsmanScorecard {
    final String playerId, playerName;
    int runs = 0, ballsFaced = 0, fours = 0, sixes = 0;
    String dismissalType = null;
    boolean isOut = false;

    public BatsmanScorecard(Player p) {
        this.playerId = p.playerId(); this.playerName = p.name();
    }

    public void addRuns(int r, boolean boundary) {
        runs += r;
        if (boundary && r == 4) fours++;
        if (boundary && r == 6) sixes++;
    }
    public void facedBall() { ballsFaced++; }
    public void dismiss(String type) { isOut = true; dismissalType = type; }
    public double getStrikeRate() {
        return ballsFaced == 0 ? 0 : (runs * 100.0) / ballsFaced;
    }
}

class BowlerScorecard {
    final String playerId, playerName;
    int legalBallsBowled = 0, runsConceded = 0, wickets = 0;
    int maidens = 0, wides = 0, noBalls = 0;

    public BowlerScorecard(Player p) {
        this.playerId = p.playerId(); this.playerName = p.name();
    }

    public void recordDelivery(int runsThisBall, boolean isLegal,
                               boolean isWicket, ExtraType extra) {
        runsConceded += runsThisBall;
        if (isLegal) legalBallsBowled++;
        if (isWicket) wickets++;
        if (extra == ExtraType.WIDE) wides++;
        if (extra == ExtraType.NO_BALL) noBalls++;
    }

    public void recordMaiden() { maidens++; }

    public String getOvers() {
        return (legalBallsBowled / 6) + "." + (legalBallsBowled % 6);
    }
    public double getEconomyRate() {
        double overs = legalBallsBowled / 6.0;
        return overs == 0 ? 0 : runsConceded / overs;
    }
}

class Innings {
    private final Team battingTeam;
    private final Team bowlingTeam;
    private final int oversLimit;
    private final int target;           // 0 for 1st innings
    private final List<Over> overs = new ArrayList<>();
    private Over currentOver;
    private BatsmanScorecard striker;
    private BatsmanScorecard nonStriker;
    private final Queue<Player> waitingBatsmen = new LinkedList<>();
    private final List<BatsmanScorecard> batsmanCards = new ArrayList<>();
    private final Map<String, BowlerScorecard> bowlerCards = new LinkedHashMap<>();
    int totalRuns = 0, totalWickets = 0, totalExtras = 0;
    boolean isComplete = false;

    public Innings(Team batting, Team bowling, int oversLimit, int target) {
        this.battingTeam = batting;
        this.bowlingTeam = bowling;
        this.oversLimit = oversLimit;
        this.target = target;

        // Initialize batting order: first two open, rest in queue
        List<Player> players = batting.players();
        striker = createBatsmanCard(players.get(0));
        nonStriker = createBatsmanCard(players.get(1));
        for (int i = 2; i < players.size(); i++) waitingBatsmen.add(players.get(i));
    }

    // ── The core method — called per delivery ──
    public void recordBall(int runs, ExtraType extra, Wicket wicket, boolean boundary) {
        if (isComplete)
            throw new InningsAlreadyOverException("Innings is over");

        // Ensure we have a current over
        if (currentOver == null || currentOver.isComplete()) {
            currentOver = new Over(overs.size(), /* bowlerId provided externally */ "");
            overs.add(currentOver);
        }

        Ball ball = new Ball(runs, extra, computeExtraRuns(extra),
            wicket, boundary, striker.playerId, currentOver.bowlerId);
        currentOver.addBall(ball);

        boolean isLegal = ball.isLegalDelivery();
        int batsmanRuns = runs;          // runs credited to batsman
        int totalBallRuns = ball.totalRuns();

        // ── Scoring rules per extra type ──
        switch (extra) {
            case WIDE -> {
                totalExtras += 1 + runs;  // 1 penalty + any runs
                totalRuns += 1 + runs;
                getBowlerCard(currentOver.bowlerId).recordDelivery(1 + runs, false, wicket != null, extra);
                // Batsman doesn't face the ball on a wide
                batsmanRuns = 0;
            }
            case NO_BALL -> {
                totalExtras += 1;         // 1 penalty
                totalRuns += 1 + runs;    // penalty + any runs scored
                striker.facedBall();       // batsman faces the ball
                striker.addRuns(runs, boundary);
                getBowlerCard(currentOver.bowlerId).recordDelivery(1 + runs, false, wicket != null, extra);
            }
            case BYE, LEG_BYE -> {
                totalExtras += runs;      // runs go to extras, not batsman
                totalRuns += runs;
                striker.facedBall();       // legal delivery — batsman faced it
                getBowlerCard(currentOver.bowlerId).recordDelivery(0, true, wicket != null, extra);
            }
            case NONE -> {
                totalRuns += runs;
                striker.facedBall();
                striker.addRuns(runs, boundary);
                getBowlerCard(currentOver.bowlerId).recordDelivery(runs, true, wicket != null, extra);
            }
        }

        // ── Wicket handling ──
        if (wicket != null) {
            handleWicket(wicket);
            if (isComplete) return;
        }

        // ── Strike rotation ──
        // Odd runs off bat → swap (except on wide with no bat runs)
        if (extra != ExtraType.WIDE && runs % 2 == 1) rotateStrike();

        // ── Over end? ──
        if (isLegal) {
            currentOver.legalBallCount++;
            if (currentOver.isComplete()) {
                endOver();
            }
        }

        // ── Innings end check ──
        checkInningsEnd();
    }

    private void handleWicket(Wicket wicket) {
        totalWickets++;
        // Find and dismiss the batsman
        BatsmanScorecard dismissed = (wicket.dismissedPlayerId().equals(striker.playerId))
            ? striker : nonStriker;
        dismissed.dismiss(wicket.dismissalType());

        // Bring in next batsman (if available)
        if (waitingBatsmen.isEmpty()) {
            isComplete = true; // ALL OUT
            return;
        }
        BatsmanScorecard newBatsman = createBatsmanCard(waitingBatsmen.poll());
        if (dismissed == striker) striker = newBatsman;
        else nonStriker = newBatsman;
    }

    private void endOver() {
        // Maiden check: 0 runs off the bat in the entire over
        if (currentOver.isMaiden()) {
            getBowlerCard(currentOver.bowlerId).recordMaiden();
        }
        // Swap strike at end of over
        rotateStrike();
    }

    private void rotateStrike() {
        BatsmanScorecard temp = striker;
        striker = nonStriker;
        nonStriker = temp;
    }

    private void checkInningsEnd() {
        if (isComplete) return;
        // All out
        if (totalWickets >= 10) { isComplete = true; return; }
        // Overs exhausted
        int legalBalls = overs.stream().mapToInt(o -> o.legalBallCount).sum();
        if (legalBalls >= oversLimit * 6) { isComplete = true; return; }
        // Target chased (2nd innings)
        if (target > 0 && totalRuns >= target) { isComplete = true; }
    }

    private int computeExtraRuns(ExtraType extra) {
        return (extra == ExtraType.WIDE || extra == ExtraType.NO_BALL) ? 1 : 0;
    }

    private BatsmanScorecard createBatsmanCard(Player p) {
        BatsmanScorecard card = new BatsmanScorecard(p);
        batsmanCards.add(card);
        return card;
    }

    private BowlerScorecard getBowlerCard(String bowlerId) {
        return bowlerCards.computeIfAbsent(bowlerId,
            id -> new BowlerScorecard(bowlingTeam.players().stream()
                .filter(p -> p.playerId().equals(id)).findFirst().orElseThrow()));
    }

    public String getOversSummary() {
        int legal = overs.stream().mapToInt(o -> o.legalBallCount).sum();
        return (legal / 6) + "." + (legal % 6);
    }
}

class Over {
    final int overNumber;
    final String bowlerId;
    final List<Ball> balls = new ArrayList<>();
    int legalBallCount = 0;

    public Over(int overNumber, String bowlerId) {
        this.overNumber = overNumber; this.bowlerId = bowlerId;
    }

    public void addBall(Ball b) { balls.add(b); }
    public boolean isComplete() { return legalBallCount >= 6; }

    public boolean isMaiden() {
        if (!isComplete()) return false;
        return balls.stream()
            .filter(Ball::isLegalDelivery)
            .allMatch(b -> b.runs == 0 && b.extraType == ExtraType.NONE);
    }
}

class Match {
    private final String matchId;
    private final Team[] teams = new Team[2];
    private final int oversLimit;
    private final List<Innings> inningsList = new ArrayList<>();
    private int currentInningsIndex = -1;
    private MatchState state = MatchState.NOT_STARTED;
    private String result;

    public Match(String matchId, Team team1, Team team2, int oversLimit, int batFirstIndex) {
        this.matchId = matchId;
        this.teams[0] = team1;
        this.teams[1] = team2;
        this.oversLimit = oversLimit;
        // Start first innings
        startInnings(batFirstIndex);
        state = MatchState.IN_PROGRESS;
    }

    private void startInnings(int battingTeamIndex) {
        int bowlingIndex = 1 - battingTeamIndex;
        int target = (inningsList.size() == 1)
            ? inningsList.get(0).totalRuns + 1 : 0;
        Innings innings = new Innings(
            teams[battingTeamIndex], teams[bowlingIndex], oversLimit, target);
        inningsList.add(innings);
        currentInningsIndex = inningsList.size() - 1;
    }

    public void recordBall(int runs, ExtraType extra, Wicket wicket,
                            boolean boundary, String currentBowlerId) {
        if (state == MatchState.COMPLETED)
            throw new MatchAlreadyOverException("Match is over: " + result);

        Innings current = inningsList.get(currentInningsIndex);

        // Set bowler on current over if it's a new over
        // (In production, bowler selection is a separate action)
        if (current.currentOver == null || current.currentOver.isComplete()) {
            // bowlerId would be set via a separate `setBowler` method
        }

        current.recordBall(runs, extra, wicket, boundary);

        if (current.isComplete) {
            if (currentInningsIndex == 0) {
                // First innings done — start second
                int secondBatIndex = (teams[0] == current.battingTeam) ? 1 : 0;
                startInnings(secondBatIndex);
            } else {
                // Second innings done — determine result
                state = MatchState.COMPLETED;
                result = computeResult();
            }
        }
    }

    private String computeResult() {
        Innings first = inningsList.get(0);
        Innings second = inningsList.get(1);

        if (second.totalRuns > first.totalRuns) {
            int wicketsRemaining = 10 - second.totalWickets;
            return second.battingTeam.teamName() + " won by " + wicketsRemaining + " wickets";
        } else if (first.totalRuns > second.totalRuns) {
            int runMargin = first.totalRuns - second.totalRuns;
            return first.battingTeam.teamName() + " won by " + runMargin + " runs";
        } else {
            return "Match tied";
        }
    }

    public MatchState getState() { return state; }
    public String getResult() { return result; }
    public List<Innings> getInnings() { return Collections.unmodifiableList(inningsList); }
}
